170	  /* --------------------------------------------------------------- shaders */
171	  var VERT = [
172	    'uniform float uTime; uniform float uSway; uniform float uHover; uniform vec2 uPointer;',
173	    'varying vec2 vUv; varying float vShade; varying vec3 vN;',
174	    'float w(vec2 p, float t){',
175	    '  return sin(p.x*2.6 + t*0.85)*0.055 + sin(p.y*2.1 - t*0.62)*0.042 + sin((p.x+p.y)*4.3 + t*1.15)*0.02;',
176	    '}',
177	    'void main(){',
178	    '  vUv = uv;',
179	    '  float hang = 1.0 - smoothstep(0.0, 1.0, uv.y);',
180	    '  float amp = (0.3 + hang) * uSway;',
181	    '  float base = w(position.xy, uTime) * amp;',
182	    '  float d = distance(position.xy, uPointer * vec2(1.5, 1.0));',
183	    '  float push = exp(-d*d*1.5) * uHover * 0.32;',
184	    '  vec3 pos = position; pos.z += base + push;',
185	    '  float e = 0.08;',
186	    '  float dx = (w(position.xy + vec2(e,0.0), uTime)*amp - base)/e;',
187	    '  float dy = (w(position.xy + vec2(0.0,e), uTime)*amp - base)/e;',
188	    '  vec3 n = normalize(vec3(-dx, -dy, 1.0)); vN = n;',
189	    '  vShade = clamp(dot(n, normalize(vec3(-0.42, 0.55, 0.72))), 0.0, 1.0);',
190	    '  gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);',
191	    '}'
192	  ].join('\n');
193	
194	  var FRAG = [
195	    'uniform sampler2D uA; uniform sampler2D uB; uniform float uMix; uniform vec2 uWipe;',
196	    'uniform float uGrain; uniform float uExp; uniform vec3 uRim;',
197	    'varying vec2 vUv; varying float vShade; varying vec3 vN;',
198	    'float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }',
199	    'void main(){',
200	    '  vec4 a = texture2D(uA, vUv); vec4 b = texture2D(uB, vUv);',
201	    '  float r = uMix * 1.95;',
202	    '  float dn = distance(vUv, uWipe) + (h21(floor(vUv*180.0)) - 0.5) * 0.06;',
203	    '  float edge = smoothstep(r - 0.24, r + 0.03, dn);',
204	    '  vec4 col = mix(b, a, edge);',
205	    '  if (col.a < 0.01) discard;',
206	    '  vec3 rgb = col.rgb * (0.68 + 0.52 * vShade) * uExp;',
207	    '  rgb *= mix(0.84, 1.05, smoothstep(0.0, 1.0, vUv.y));',
208	    '  rgb += uRim * pow(clamp(1.0 - vN.z, 0.0, 1.0), 2.0) * 0.4;',
209	    '  float g = h21(vUv * vec2(820.0, 560.0));',
210	    '  rgb *= 1.0 + (g - 0.5) * uGrain;',
211	    '  gl_FragColor = vec4(rgb, col.a);',
212	    '}'
213	  ].join('\n');
214	
215	  var HAZE_FRAG = [
216	    'uniform float uTime; varying vec2 vUv;',
217	    'float h21(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }',
218	    'float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);',
219	    '  return mix(mix(h21(i), h21(i+vec2(1.0,0.0)), f.x), mix(h21(i+vec2(0.0,1.0)), h21(i+vec2(1.0,1.0)), f.x), f.y); }',
220	    'void main(){',
221	    '  vec2 p = vUv * vec2(3.2, 2.0);',
222	    '  float t = uTime * 0.045;',
223	    '  float f = vn(p + vec2(t, -t*0.6)) * 0.55 + vn(p*2.1 - vec2(t*1.4, t)) * 0.3 + vn(p*4.3 + vec2(t*0.7, t*1.1)) * 0.15;',
224	    '  float fall = smoothstep(1.0, 0.15, distance(vUv, vec2(0.42, 0.55)) * 1.7);',
225	    '  vec3 c = mix(vec3(0.49, 0.09, 0.15), vec3(0.89, 0.74, 0.59), f);',
226	    '  gl_FragColor = vec4(c, f * fall * 0.16);',
227	    '}'
228	  ].join('\n');
