230	  /* ----------------------------------------------------------- cloth stage */
231	  function makeStage(canvas, opts) {
232	    if (!window.THREE) return null;
233	    var renderer;
234	    try {
235	      /* premultipliedAlpha:false keeps straight-alpha maths — the cutouts have
236	         feathered edges and additive haze/motes rely on SRC_ALPHA blending */
237	      renderer = new THREE.WebGLRenderer({
238	        canvas: canvas, alpha: true, antialias: true, premultipliedAlpha: false
239	      });
240	    } catch (e) { return null; }
241	    if (!renderer.getContext()) return null;
242	
243	    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, opts.dpr || 2));
244	    renderer.setClearColor(0x000000, 0);
245	
246	    var scene = new THREE.Scene();
247	    var camera = new THREE.PerspectiveCamera(34, 1, 0.1, 60);
248	    camera.position.z = opts.z || 6;
249	
250	    var loader = new THREE.TextureLoader();
251	    function tex(url) {
252	      var t = loader.load(url);
253	      t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
254	      t.minFilter = THREE.LinearMipmapLinearFilter;
255	      t.magFilter = THREE.LinearFilter;
256	      return t;
257	    }
258	    var maps = COLOURWAYS.map(function (c) { return tex(c.tex); });
259	
260	    var uni = {
261	      uTime: { value: 0 }, uSway: { value: opts.sway || 1 }, uHover: { value: 0 },
262	      uPointer: { value: new THREE.Vector2(0, 0) },
263	      uA: { value: maps[0] }, uB: { value: maps[0] }, uMix: { value: 0 },
264	      uWipe: { value: new THREE.Vector2(0.5, 0.5) },
265	      uGrain: { value: 0.07 }, uExp: { value: opts.exp || 1.06 },
266	      uRim: { value: new THREE.Color(opts.rim || 0x5d3a33) }
267	    };
268	
269	    var segs = opts.segs || [44, 32];
270	    var W = opts.width || 3.4;
271	    /* the four cutouts average 1.477:1 — keep the plane on that ratio so
272	       no colourway gets stretched when it swaps in */
273	    var geo = new THREE.PlaneGeometry(W, W * 0.677, segs[0], segs[1]);
274	    var mat = new THREE.ShaderMaterial({
275	      vertexShader: VERT, fragmentShader: FRAG, uniforms: uni,
276	      transparent: true, depthWrite: false, side: THREE.DoubleSide
277	    });
278	    var cloth = new THREE.Mesh(geo, mat);
279	    var group = new THREE.Group();
280	    group.add(cloth);
281	    scene.add(group);
282	
283	    /* haze */
284	    var haze = null;
285	    if (opts.haze) {
286	      haze = new THREE.Mesh(
287	        new THREE.PlaneGeometry(16, 10),
288	        new THREE.ShaderMaterial({
289	          uniforms: { uTime: uni.uTime },
290	          vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
291	          fragmentShader: HAZE_FRAG,
292	          transparent: true, depthWrite: false, blending: THREE.AdditiveBlending
293	        })
294	      );
295	      haze.position.z = -5;
296	      scene.add(haze);
297	    }
298	
299	    /* fibre motes */
300	    var motes = null, mv = null;
301	    if (opts.motes && !REDUCED) {
302	      var n = opts.motes;
303	      var c = document.createElement('canvas'); c.width = c.height = 64;
304	      var g2 = c.getContext('2d');
305	      var rg = g2.createRadialGradient(32, 32, 0, 32, 32, 32);
306	      rg.addColorStop(0, 'rgba(255,238,220,1)');
307	      rg.addColorStop(0.35, 'rgba(255,228,205,.45)');
308	      rg.addColorStop(1, 'rgba(255,220,200,0)');
309	      g2.fillStyle = rg; g2.fillRect(0, 0, 64, 64);
310	      var sprite = new THREE.CanvasTexture(c);
311	      var pos = new Float32Array(n * 3);
312	      mv = new Float32Array(n);
313	      for (var i = 0; i < n; i++) {
314	        pos[i * 3] = (Math.random() - 0.5) * 7.5;
315	        pos[i * 3 + 1] = (Math.random() - 0.5) * 5.2;
316	        pos[i * 3 + 2] = -Math.random() * 2.6 - 0.2;
317	        mv[i] = 0.04 + Math.random() * 0.1;
318	      }
319	      var pg = new THREE.BufferGeometry();
320	      pg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
321	      motes = new THREE.Points(pg, new THREE.PointsMaterial({
322	        map: sprite, size: 0.055, transparent: true, opacity: 0.5,
323	        blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
324	      }));
325	      scene.add(motes);
326	    }
327	
328	    var st = {
329	      visible: true, prog: 0, target: { rx: 0, ry: 0, px: 0, py: 0 },
330	      cur: { rx: 0, ry: 0, px: 0, py: 0 }, spin: 0, spinV: 0, idx: 0, mixing: false,
331	      offX: 0, want: -1, wantWipe: null
332	    };
333	
334	    function resize() {
335	      var w = canvas.clientWidth || canvas.parentNode.clientWidth;
336	      var h = canvas.clientHeight || canvas.parentNode.clientHeight;
337	      if (!w || !h) return;
338	      renderer.setSize(w, h, false);
339	      camera.aspect = w / h;
340	      camera.updateProjectionMatrix();
341	      var wide = w / h > 1.15;
342	      st.offX = opts.shift ? (wide ? -0.92 : 0) : 0;
343	      var s = opts.shift ? (wide ? 1 : 0.82) : 1;
344	      group.scale.setScalar(s);
345	    }
346	
347	    function setColour(i, wipe) {
348	      if (i === st.idx) { st.want = -1; return; }
349	      if (st.mixing) { st.want = i; st.wantWipe = wipe; return; }
350	      st.want = -1;
351	      st.idx = i;
352	      uni.uB.value = maps[i];
353	      uni.uWipe.value.set(wipe ? wipe[0] : 0.5, wipe ? wipe[1] : 0.62);
354	      uni.uMix.value = 0;
355	      st.mixing = true;
356	    }
357	
358	    function tick(dt, t) {
359	      uni.uTime.value = t;
360	      if (st.mixing) {
361	        uni.uMix.value += dt * 1.25;
362	        if (uni.uMix.value >= 1) {
363	          uni.uMix.value = 0; uni.uA.value = uni.uB.value; st.mixing = false;
364	          if (st.want >= 0) setColour(st.want, st.wantWipe);
365	        }
366	      }
367	      var k = 1 - Math.pow(0.001, dt);
368	      st.cur.rx = lerp(st.cur.rx, st.target.rx, k);
369	      st.cur.ry = lerp(st.cur.ry, st.target.ry, k);
370	      st.cur.px = lerp(st.cur.px, st.target.px, k);
371	      st.cur.py = lerp(st.cur.py, st.target.py, k);
372	      uni.uPointer.value.set(st.cur.px * 1.4, st.cur.py * 1.0);
373	      uni.uHover.value = lerp(uni.uHover.value, st.hover ? 1 : 0.25, k);
374	
375	      if (opts.drag) {
376	        st.spin += st.spinV * dt;
377	        st.spinV *= Math.pow(0.06, dt);
378	        if (!st.dragging && !REDUCED) st.spin += dt * 0.06;
379	      }
380	
381	      var p = st.prog;
382	      group.rotation.y = st.cur.ry + st.spin + (opts.shift ? -0.2 + p * 0.42 : 0);
383	      group.rotation.x = st.cur.rx + (opts.shift ? 0.05 - p * 0.1 : 0);
384	      group.rotation.z = (opts.shift ? 0.02 - p * 0.06 : 0) + st.cur.px * 0.04;
385	      group.position.x = st.offX + st.cur.px * 0.16;
386	      group.position.y = (opts.shift ? 0.28 - p * 0.16 : 0) - st.cur.py * 0.14;
387	      if (opts.shift) {
388	        camera.position.z = (opts.z || 6) - 1.35 * Math.sin(p * Math.PI);
389	        camera.position.x = st.cur.px * -0.25;
390	        uni.uSway.value = (REDUCED ? 0.3 : 0.8) + p * 0.55;
391	      }
392	      if (motes) {
393	        var arr = motes.geometry.attributes.position.array;
394	        for (var i = 0; i < mv.length; i++) {
395	          arr[i * 3 + 1] += mv[i] * dt;
396	          arr[i * 3] += Math.sin(t * 0.3 + i) * dt * 0.03;
397	          if (arr[i * 3 + 1] > 2.7) { arr[i * 3 + 1] = -2.7; arr[i * 3] = (Math.random() - 0.5) * 7.5; }
398	        }
399	        motes.geometry.attributes.position.needsUpdate = true;
400	        motes.rotation.y = st.cur.px * 0.08;
401	      }
402	      renderer.render(scene, camera);
403	    }
404	
405	    resize();
406	    return {
407	      tick: tick, resize: resize, setColour: setColour, st: st,
408	      setProgress: function (p) { st.prog = p; },
409	      pointer: function (x, y, hov) { st.target.px = x; st.target.py = y; st.hover = hov; st.target.ry = x * 0.22; st.target.rx = -y * 0.12; },
410	      spinBy: function (d) { st.spinV += d; },
411	      dragging: function (b) { st.dragging = b; }
412	    };
413	  }
